use chrono::{Datelike, NaiveDate};
use std::collections::BTreeMap;

use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLABLE_SECONDS: i64 = 30 * 60;

#[derive(Debug, PartialEq)]
struct WeeklyBilling {
    weeks: BTreeMap<NaiveDate, i64>,
}

impl WeeklyBilling {
    fn total_seconds(&self) -> i64 {
        self.weeks.values().sum()
    }
}

/// Apply the shop's billing rule to one stopped, billable entry.
pub(crate) fn billable_seconds(entry: &TimeEntry) -> Option<i64> {
    if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
        return None;
    }

    let rounded = ((entry.duration + BILLING_INCREMENT_SECONDS - 1) / BILLING_INCREMENT_SECONDS)
        * BILLING_INCREMENT_SECONDS;
    Some(rounded.max(MINIMUM_BILLABLE_SECONDS))
}

fn monday_for(entry: &TimeEntry) -> NaiveDate {
    entry.start.date_naive()
        - chrono::Duration::days(entry.start.weekday().num_days_from_monday() as i64)
}

fn aggregate(entries: &[TimeEntry]) -> WeeklyBilling {
    let mut weeks = BTreeMap::new();
    for entry in entries {
        if let Some(seconds) = billable_seconds(entry) {
            *weeks.entry(monday_for(entry)).or_insert(0) += seconds;
        }
    }
    WeeklyBilling { weeks }
}

pub struct BillWeeklyCommand;

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let billing = aggregate(&entries);
        if json {
            let weeks: Vec<_> = billing
                .weeks
                .iter()
                .map(|(week, seconds)| {
                    serde_json::json!({
                        "week": week.format("%Y-%m-%d").to_string(),
                        "billable_seconds": seconds,
                    })
                })
                .collect();
            println!(
                "{}",
                serde_json::json!({
                    "weeks": weeks,
                    "total_billable_seconds": billing.total_seconds(),
                })
            );
        } else if billing.weeks.is_empty() {
            println!("(no data)");
        } else {
            for (week, seconds) in &billing.weeks {
                println!("{}  {seconds}s", week.format("%Y-%m-%d"));
            }
            println!("Total  {}s", billing.total_seconds());
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{TimeZone, Utc};

    fn entry(start: &str, duration: i64, billable: bool, stop: bool) -> TimeEntry {
        TimeEntry {
            start: Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap(),
            duration,
            billable,
            stop: stop.then_some(Utc.timestamp_opt(1_700_000_000, 0).unwrap()),
            ..TimeEntry::default()
        }
    }

    #[test]
    fn bills_each_entry_with_rounding_and_minimum() {
        assert_eq!(
            billable_seconds(&entry("2026-03-02T12:00:00Z", 1, true, true)),
            Some(1800)
        );
        assert_eq!(
            billable_seconds(&entry("2026-03-02T12:00:00Z", 1801, true, true)),
            Some(2700)
        );
        assert_eq!(
            billable_seconds(&entry("2026-03-02T12:00:00Z", 3600, true, true)),
            Some(3600)
        );
    }

    #[test]
    fn excludes_non_billable_and_running_entries() {
        assert_eq!(
            billable_seconds(&entry("2026-03-02T12:00:00Z", 3600, false, true)),
            None
        );
        assert_eq!(
            billable_seconds(&entry("2026-03-02T12:00:00Z", -1, true, false)),
            None
        );
    }

    #[test]
    fn groups_by_utc_iso_week_monday_in_order() {
        let billing = aggregate(&[
            entry("2026-03-08T23:00:00Z", 900, true, true),
            entry("2026-03-02T00:00:00Z", 3600, true, true),
            entry("2026-03-09T00:00:00Z", 900, true, true),
        ]);
        assert_eq!(
            billing,
            WeeklyBilling {
                weeks: BTreeMap::from([
                    (NaiveDate::from_ymd_opt(2026, 3, 2).unwrap(), 5400),
                    (NaiveDate::from_ymd_opt(2026, 3, 9).unwrap(), 1800),
                ])
            }
        );
    }
}

    WeeklyBilling { weeks }
